type PuzzleData = z.infer<
  (typeof publicContract.getPuzzleState.responses)["200"]
>;
type Guesses = PuzzleData["guesses"];
type Guess = Guesses[number];

type PuzzleWindowState = {
  initialTeamState: TeamHuntState;
  initialTeamInfo?: TeamInfo;
  initialTeamId?: number;
  puzzleSlug: string;
  roundSlug?: string;
  initialPuzzleState?: PuzzleData;
  initialPuzzleStateLog?: PuzzleStateLogEntry[];
  initialKingdomRunaroundAssignments?: KingdomRunaroundAssignment[];
};
const MAX_LOCAL_GUESSES = 2000;
const LOCAL_SOLVED_EVENT = "hunt.puzzles.solved.updated";

const isGuessLike = (value: unknown): value is Guess => {
  if (!value || typeof value !== "object") return false;
  const guess = value as Partial<Guess>;
  if (typeof guess.id !== "number") return false;
  if (typeof guess.canonical_input !== "string") return false;
  if (typeof guess.status !== "string") return false;
  if (typeof guess.response !== "string") return false;
  if (typeof guess.timestamp !== "string") return false;
  return true;
};

const loadLocalGuessLog = (slug: string): Guess[] => {
  if (typeof window === "undefined") return [];
  try {
    const raw = window.localStorage.getItem(getLocalGuessLogKey(slug));
    if (!raw) return [];
    const parsed = JSON.parse(raw) as unknown;
    if (!Array.isArray(parsed)) return [];
    return parsed.filter(isGuessLike);
  } catch {
    return [];
  }
};

const persistLocalGuessLog = (slug: string, guesses: Guess[]) => {
  if (typeof window === "undefined") return;
  try {
    if (guesses.length === 0) {
      window.localStorage.removeItem(getLocalGuessLogKey(slug));
      return;
    }
    const trimmed =
      guesses.length > MAX_LOCAL_GUESSES
        ? guesses.slice(guesses.length - MAX_LOCAL_GUESSES)
        : guesses;
    window.localStorage.setItem(
      getLocalGuessLogKey(slug),
      JSON.stringify(trimmed),
    );
  } catch {
    // Ignore storage failures.
  }
};

const ensureSolvedGuess = (slug: string, guesses: Guess[]): Guess[] => {
  if (guesses.some((guess) => guess.status === "correct")) {
    return guesses;
  }
  const solvedEntry = getLocalSolvedPuzzleMap()[slug];
  if (!solvedEntry) return guesses;
  const answer = solvedEntry.answer ?? "Solved";
  const solvedGuess: Guess = {
    id: Date.now(),
    canonical_input: answer,
    status: "correct",
    response: "Correct",
    timestamp: new Date().toISOString(),
  };
  return guesses.concat(solvedGuess);
};

const mergeGuesses = (oldGuesses: Guess[], newGuesses: Guess[]): Guess[] => {
  // Merge the previous guess set and the new one together, retaining any common entries exactly once.
  const canonicalInputs = new Set();
  const mergedGuesses: Guess[] = [];
  const processGuess = (guess: Guess) => {
    if (!canonicalInputs.has(guess.canonical_input)) {
      canonicalInputs.add(guess.canonical_input);
      mergedGuesses.push(guess);
    }
  };
  oldGuesses.forEach(processGuess);
  newGuesses.forEach(processGuess);
  // Sort by id
  mergedGuesses.sort((a, b) => a.id - b.id);
  return mergedGuesses;
};

const areGuesses = (guesses: unknown): guesses is Guess[] => {
  // Just sanity check that the value has some of the correct fields.
  return (
    typeof guesses === "object" &&
    Array.isArray(guesses) &&
    guesses.every(
      (guess: unknown) =>
        typeof guess === "object" &&
        guess &&
        "status" in guess &&
        guess.status &&
        "id" in guess &&
        guess.id !== null &&
        guess.id !== undefined,
    )
  );
};

const GuessSectionManager = ({
  initialGuesses,
  initialTeamState,
  slug,
  renderPostSolve,
}: {
  initialGuesses: Guesses;
  initialTeamState: TeamHuntState;
  slug: string;
  renderPostSolve: boolean;
}) => {
  const mergedInitialGuesses = useMemo(() => {
    if (!IS_STATIC_SITE) {
      return initialGuesses;
    }
    const localGuesses = loadLocalGuessLog(slug);
    return ensureSolvedGuess(slug, mergeGuesses(initialGuesses, localGuesses));
  }, [initialGuesses, slug]);
  const websocketGuesses = useAppendDataset(
    "guess_log",
    { slug },
    mergedInitialGuesses,
  );
  const [guesses, setGuesses] = useState<Guess[]>(websocketGuesses);
  const mergedGuesses = useMemo(
    () => mergeGuesses(guesses, websocketGuesses),
    [guesses, websocketGuesses],
  );
  const hash = useMemo(() => md5(slug), [slug]);

  useEffect(() => {
    // This is a hash of "keep_going" - we do this instead of comparing the strings
    // directly because then "keep_going" would appear in the frontend source code.
    if (hash === "ec21e4be818085d31ea394add83c29b4") {
      const parsed: unknown = JSON.parse(
        window.localStorage.getItem(
          "ec21e4be818085d31ea394add83c29b4_history",
        ) ?? "[]",
      );

      if (!areGuesses(parsed)) {
        throw new Error("expected guess");
      }

      setGuesses(parsed);
    }
  }, [hash]);

  useEffect(() => {
    // This is a hash of "keep_going" - we do this instead of comparing the strings
    // directly because then "keep_going" would appear in the frontend source code.
    if (hash === "ec21e4be818085d31ea394add83c29b4") {
      let truncated = guesses;
      // Just set some limit for the guess count so we don't run out of local storage space (5 MB-10MB in
      // most browsers).
      if (guesses.length > 2000) {
        truncated = guesses.slice(guesses.length - 2000);
      }

      window.localStorage.setItem(
        "ec21e4be818085d31ea394add83c29b4_history",
        JSON.stringify(truncated),
      );
    }
  }, [guesses, hash]);

  useEffect(() => {
    const handleSolvedUpdate = () => {
      setGuesses((prevGuesses) => ensureSolvedGuess(slug, prevGuesses));
    };
    window.addEventListener(LOCAL_SOLVED_EVENT, handleSolvedUpdate);
    return () => {
      window.removeEventListener(LOCAL_SOLVED_EVENT, handleSolvedUpdate);
    };
  }, [slug]);

  const onGuessesUpdate = useCallback(
    (newGuesses: Guess[]) => {
      setGuesses((prevGuesses: Guess[]) => {
        const merged = mergeGuesses(prevGuesses, newGuesses);
        if (!renderPostSolve) {
          return merged;
        }
        if (
          !IS_STATIC_SITE &&
          newGuesses.some((guess) => guess.status === "correct")
        ) {
          // Refresh the page to show the post-solve section.
          window.location.reload();
        }
        return merged;
      });
    },
    [renderPostSolve],
  );

  useEffect(() => {
    if (!IS_STATIC_SITE) return;
    persistLocalGuessLog(slug, mergedGuesses);
  }, [mergedGuesses, slug]);

  const teamState = useDataset("team_state", undefined, initialTeamState);
  const taskDev = (window as unknown as { taskDev: boolean }).taskDev;
  const showSubmissionForm = (
    window as unknown as { showSubmissionForm: boolean }
  ).showSubmissionForm;
  const googleFormsLink = (window as unknown as { googleFormsLink: string })
    .googleFormsLink;
  const taskSubmissionState = (
    window as unknown as {
      taskSubmissionState?: "submittable" | "pending_grade" | "complete";
    }
  ).taskSubmissionState;
  const taskSubmissions = (
    window as unknown as {
      taskSubmissions?: TaskSubmissionHistoryEntry[];
    }
  ).taskSubmissions;

  return (
    <PuzzleGuessSection
      slug={slug}
      guesses={mergedGuesses}
      onGuessesUpdate={onGuessesUpdate}
      teamState={teamState}
      showTaskDev={taskDev}
      showSubmissionForm={showSubmissionForm}
      googleFormsLink={googleFormsLink}
      taskSubmissionState={taskSubmissionState}
      taskSubmissions={taskSubmissions}
    />
  );
};

const HyperbolicSpacePostSolveClient = ({
  slug,
  initialTeamState,
}: {
  slug: string;
  initialTeamState: TeamHuntState;
}) => {
  const { solvedMap } = useSolvedPuzzlesState();
  const mergedTeamState = useMemo(
    () => applySolvedMapToTeamState(initialTeamState, solvedMap),
    [initialTeamState, solvedMap],
  );
  return (
    <TeamStateProvider teamState={mergedTeamState}>
      <HyperbolicSpacePostSolveSection slug={slug} />
    </TeamStateProvider>
  );
};

const SubpuzzleGuessSectionManager = ({
  initialPuzzleStateLog,
  slug,
  parentSlug,
}: {
  initialPuzzleStateLog: PuzzleStateLogEntry[];
  slug: string;
  parentSlug: string;
}) => {
  const puzzleStateLog = useAppendDataset<PuzzleStateLogEntry>(
    "puzzle_state_log",
    { slug: parentSlug },
    initialPuzzleStateLog,
  );
  // Munge the puzzle state log into the shape of a Guess.
  const websocketGuesses = puzzleStateLog
    .filter(
      (entry) =>
        entry.slug === parentSlug &&
        entry.data.subpuzzle_slug === slug &&
        entry.data.type === "subpuzzle_guess_submitted",
    )
    .map<Guess>((entry) => {
      return {
        id: entry.id,
        timestamp: entry.timestamp as unknown as string,
        canonical_input: entry.data.canonical_input as string,
        response: entry.data.response as string,
        status: entry.data.status as
          | "correct"
          | "incorrect"
          | "other"
          | "pending_grade",
      };
    });
  const [guesses, setGuesses] = useState<Guess[]>(websocketGuesses);
  const onGuessesUpdate = useCallback((newGuesses: Guess[]) => {
    setGuesses((prevGuesses: Guess[]) => {
      return mergeGuesses(prevGuesses, newGuesses);
    });
  }, []);
  return (
    <SubpuzzleGuessSection
      slug={slug}
      guesses={mergeGuesses(guesses, websocketGuesses)}
      onGuessesUpdate={onGuessesUpdate}
    />
  );
};

const buildQueryFromLocation = (): ParsedQs => {
  if (typeof window === "undefined") return {};
  const params = new URLSearchParams(window.location.search);
  const query: ParsedQs = {};
  params.forEach((value, key) => {
    const existing = query[key];
    if (existing === undefined) {
      query[key] = value;
      return;
    }
    if (Array.isArray(existing)) {
      existing.push(value);
      return;
    }
    query[key] = [existing as string, value];
  });
  return query;
};

const LandOfNoNameContent = ({
  puzzleDef,
  initialTeamState,
  initialTeamInfo,
  initialTeamId,
  initialPuzzleState,
  initialPuzzleStateLog,
  initialKingdomRunaroundAssignments,
  roundSlug,
  copyable,
}: {
  puzzleDef: (typeof PUZZLES)[string];
  initialTeamState: TeamHuntState;
  initialTeamInfo?: TeamInfo;
  initialTeamId?: number;
  initialPuzzleState: PuzzleData;
  initialPuzzleStateLog?: PuzzleStateLogEntry[];
  initialKingdomRunaroundAssignments?: KingdomRunaroundAssignment[];
  roundSlug?: string;
  copyable: boolean;
}) => {
  const { solvedLetters, showAllLetters } = useLandOfNoNameLettersState();
  const availableLetters = useMemo(() => {
    if (showAllLetters) {
      return Object.keys(ALPHABET_LETTER_TO_SLUG);
    }
    return solvedLetters.map((letter) => letter.toUpperCase());
  }, [showAllLetters, solvedLetters]);
  const teamStateWithOverride = useMemo(
    () =>
      ({
        ...initialTeamState,
        alpha_available_letters_override: availableLetters,
      }) as TeamHuntState & { alpha_available_letters_override: string[] },
    [availableLetters, initialTeamState],
  );
  const query = useMemo(() => buildQueryFromLocation(), []);
  const title = useMemo(
    () => getPuzzleTitle(puzzleDef, teamStateWithOverride),
    [puzzleDef, teamStateWithOverride],
  );
  const backlinkText = useMemo(() => {
    if (roundSlug !== ALPHABET_ROUND_SLUG) return null;
    return alphaObfuscateString(
      "Back to Land of No Name",
      teamStateWithOverride,
    );
  }, [roundSlug, teamStateWithOverride]);

  useEffect(() => {
    const titleElement = document.querySelector<HTMLElement>(
      "[data-puzzle-title-text]",
    );
    if (titleElement && titleElement.textContent !== title) {
      titleElement.textContent = title;
    }
    if (backlinkText !== null) {
      const backlinkElement = document.querySelector<HTMLElement>(
        "[data-puzzle-backlink-text]",
      );
      if (backlinkElement && backlinkElement.textContent !== backlinkText) {
        backlinkElement.textContent = backlinkText;
      }
    }
  }, [backlinkText, title]);

  const ContentComponent = puzzleDef.content.component;
  return (
    <>
      <ContentComponent
        type="puzzle"
        teamName={initialTeamInfo?.teamName ?? "Team"}
        teamId={initialTeamId ?? 0}
        teamUsername={initialTeamInfo?.teamUsername ?? ""}
        teamState={teamStateWithOverride}
        puzzleState={initialPuzzleState}
        puzzleStateLog={initialPuzzleStateLog}
        query={query}
        kingdomRunaroundAssignments={initialKingdomRunaroundAssignments}
      />
      {copyable ? (
        <CopyToClipboard className="lg:sticky lg:bottom-8 lg:ml-[860px] lg:mr-0" />
      ) : (
        <div className="lg:h-12" />
      )}
    </>
  );
};

const puzzleGuessSectionElem = document.getElementById("puzzle-guesses");
const subpuzzleGuessSectionElem = document.getElementById("subpuzzle-guesses");
if (puzzleGuessSectionElem) {
  const initialGuesses = (
    window as unknown as { initialGuesses: PuzzleData["guesses"] }
  ).initialGuesses;
  const initialTeamState = (
    window as unknown as { initialTeamState: TeamHuntState }
  ).initialTeamState;
  // TODO: extract puzzleSlug from the URL instead of embedding it via script?
  const slug = (window as unknown as { puzzleSlug: string }).puzzleSlug;
  const roundSlug = (window as unknown as { roundSlug: string }).roundSlug;
  const isMeta = (window as unknown as { isMeta: boolean }).isMeta;
  hydrateRoot(
    puzzleGuessSectionElem,
    <GuessSectionManager
      initialGuesses={initialGuesses}
      initialTeamState={initialTeamState}
      slug={slug}
      renderPostSolve={
        (roundSlug === "hyperbolic_space" && !isMeta) || slug === "at_the_close"
      }
    />,
  );
} else if (subpuzzleGuessSectionElem) {
  const initialPuzzleStateLog = (
    window as unknown as { initialPuzzleStateLog: PuzzleStateLogEntry[] }
  ).initialPuzzleStateLog;
  // TODO: extract puzzleSlug from the URL instead of embedding it via script?
  const slug = (window as unknown as { puzzleSlug: string }).puzzleSlug;
  const parentSlug = (window as unknown as { parentSlug: string }).parentSlug;
  hydrateRoot(
    subpuzzleGuessSectionElem,
    <SubpuzzleGuessSectionManager
      initialPuzzleStateLog={initialPuzzleStateLog}
      slug={slug}
      parentSlug={parentSlug}
    />,
  );
} else {
  console.error(
    "Couldn't mount PuzzleGuessSection because #puzzle-guesses and #subpuzzle-guesses were nowhere to be found",
  );
}

const puzzlePostSolveElem = document.getElementById("puzzle-post-solve");
if (puzzlePostSolveElem && IS_STATIC_SITE) {
  const windowState = window as unknown as PuzzleWindowState;
  const roundSlug = windowState.roundSlug;
  const isMeta = (window as unknown as { isMeta: boolean }).isMeta;
  if (roundSlug === "hyperbolic_space" && !isMeta) {
    const puzzleSlug = windowState.puzzleSlug;
    const initialTeamState = windowState.initialTeamState;
    if (puzzleSlug && initialTeamState) {
      const root = createRoot(puzzlePostSolveElem);
      root.render(
        <HyperbolicSpacePostSolveClient
          slug={puzzleSlug}
          initialTeamState={initialTeamState}
        />,
      );
    }
  }
}

const puzzleContent = document.getElementById("puzzle-content");
let renderedLandOfNoNameContent = false;
if (puzzleContent && IS_STATIC_SITE) {
  const windowState = window as unknown as PuzzleWindowState;
  const puzzleSlug = windowState.puzzleSlug;
  if (puzzleSlug && isAlphabetSlug(puzzleSlug)) {
    const puzzleDef = PUZZLES[puzzleSlug];
    if (
      puzzleDef &&
      windowState.initialTeamState &&
      windowState.initialPuzzleState
    ) {
      (
        window as unknown as {
          landOfNoNameClientRendered?: boolean;
          landOfNoNameClientRenderedSlug?: string;
        }
      ).landOfNoNameClientRendered = true;
      (
        window as unknown as {
          landOfNoNameClientRendered?: boolean;
          landOfNoNameClientRenderedSlug?: string;
        }
      ).landOfNoNameClientRenderedSlug = puzzleSlug;
      const root = createRoot(puzzleContent);
      root.render(
        <LandOfNoNameContent
          puzzleDef={puzzleDef}
          initialTeamState={windowState.initialTeamState}
          initialTeamInfo={windowState.initialTeamInfo}
          initialTeamId={windowState.initialTeamId}
          initialPuzzleState={windowState.initialPuzzleState}
          initialPuzzleStateLog={windowState.initialPuzzleStateLog}
          initialKingdomRunaroundAssignments={
            windowState.initialKingdomRunaroundAssignments
          }
          roundSlug={windowState.roundSlug}
          copyable={puzzleContent.dataset.copyable === "true"}
        />,
      );
      renderedLandOfNoNameContent = true;
    }
  }
}

if (puzzleContent && !renderedLandOfNoNameContent) {
  const container = document.createElement("div");
  container.style.display = "contents";
  puzzleContent.appendChild(container);
  const root = createRoot(container);
  if (puzzleContent?.dataset.copyable) {
    root.render(
      // Update the lg:ml value if the max width of the puzzle content changes.
      // We are using the max-width value minus 64px.
      <CopyToClipboard className="lg:sticky lg:bottom-8 lg:ml-[860px] lg:mr-0" />,
    );
  } else {
    // Need the extra space so that MonArch doesn't cover any puzzle content.
    root.render(<div className="lg:h-12" />);
  }
}

const puzzleHintLinkElem = document.getElementById("puzzle-hint-link");
if (puzzleHintLinkElem) {
  const slug = (
    puzzleHintLinkElem as HTMLElement & { dataset: { puzzleSlug?: string } }
  ).dataset.puzzleSlug;
  const windowState = window as unknown as {
    puzzleSlug: string;
    initialTeamState: TeamHuntState;
    roundSlug?: string;
  };
  const puzzleSlug = slug ?? windowState.puzzleSlug;
  const puzzleState = windowState.initialTeamState?.puzzles?.[puzzleSlug];
  if (puzzleState) {
    const roundSlug = windowState.roundSlug;
    const isTerminusMeta =
      roundSlug === "terminus" && puzzleSlug === "mixed_media";
    const HintComponent = isTerminusMeta
      ? TerminusMetaHintLink
      : roundSlug === "terminus"
        ? TerminusHintLink
        : HintLink;
    hydrateRoot(
      puzzleHintLinkElem,
      <HintComponent slug={puzzleSlug} puzzleState={puzzleState} />,
    );
  }
}

const puzzleErratumIconElem = document.getElementById("puzzle-erratum-icon");
if (puzzleErratumIconElem) {
  const windowState = window as unknown as {
    puzzleSlug: string;
  };
  const slug =
    (
      puzzleErratumIconElem as HTMLElement & {
        dataset: { puzzleSlug?: string; erratumType?: string };
      }
    ).dataset.puzzleSlug ?? windowState.puzzleSlug;
  const erratumType =
    (
      puzzleErratumIconElem as HTMLElement & {
        dataset: { erratumType?: string };
      }
    ).dataset.erratumType === "task"
      ? "task"
      : "puzzle";
  const hasErratum =
    (
      puzzleErratumIconElem as HTMLElement & {
        dataset: { hasErratum?: string };
      }
    ).dataset.hasErratum === "true";
  hydrateRoot(
    puzzleErratumIconElem,
    <ErratumIcon
      resource={{ type: erratumType, slug }}
      hasErratum={hasErratum}
      iconClassName="h-5 w-5"
    />,
  );
}
