import { type TeamHuntState } from "@hunt/public-client";
import { ConditionalTooltip } from "@hunt/shadcn";
import { cn } from "@hunt/styled-ui";
import React, { useState, useEffect } from "react";
import { HintBadge } from "./HintBadge";

const HintLinkWrapper = ({
  children,
  className,
}: {
  children: React.ReactNode;
  className?: string;
}) => <div className={cn("inline-flex", className)}>{children}</div>;

export default function HintLink({
  slug,
  puzzleState,
}: {
  slug: string;
  puzzleState: TeamHuntState["puzzles"][string];
}) {
  const hintsUnlockedAt = puzzleState.hints_unlocked_at;
  const solved = !!puzzleState.answer;
  const isResearchTask = puzzleState.task_info !== undefined;

  const [unlocked, setUnlocked] = useState(
    hintsUnlockedAt && new Date(hintsUnlockedAt).getTime() < Date.now(),
  );

  useEffect(() => {
    if (hintsUnlockedAt && !unlocked) {
      const interval = setInterval(() => {
        if (new Date(hintsUnlockedAt).getTime() < Date.now()) {
          setUnlocked(true);
        }
      }, 5000);

      return () => {
        clearInterval(interval);
      };
    }

    return () => {
      // noop
    };
  }, [hintsUnlockedAt, unlocked]);

  if (solved || !hintsUnlockedAt) {
    return null;
  }

  const baseUrl = isResearchTask ? "/research_tasks" : "/puzzles";
  const hintAvailableAt = new Date(hintsUnlockedAt).toLocaleString("en-US");
  const tooltip = unlocked
    ? undefined
    : `Hints will be available for this puzzle at ${hintAvailableAt}`;

  return (
    <HintLinkWrapper className="pr-0.5">
      <ConditionalTooltip tooltip={tooltip}>
        <HintBadge
          disabled={!unlocked}
          href={`${baseUrl}/${slug}/hints`}
          aria-label="Hints"
        />
      </ConditionalTooltip>
    </HintLinkWrapper>
  );
}
