import { type TeamHuntState } from "@hunt/public-client";
import { cn } from "@hunt/styled-ui";
import React from "react";
import HintLink from "../HintLink";
import {
  type PuzzleTitleProps,
  type PuzzleHeaderProps,
  type PuzzleWrapperProps,
} from "../PuzzleLayout";
import terminusBg from "./assets/terminus_puzzle_bg.png";

export function TerminusPuzzleWrapper({
  children,
  className = "",
  style,
  ...props
}: PuzzleWrapperProps) {
  const mergedStyle: React.CSSProperties = {
    backgroundImage: `url(${terminusBg})`,
    backgroundRepeat: "no-repeat",
    backgroundSize: "100% auto",
    backgroundPosition: "top center",
    backgroundColor: "#329ACE",
    ...(style || {}),
  };

  return (
    <div
      {...props}
      style={mergedStyle}
      className={cn(
        "w-screen aspect-16/9 text-black min-h-screen pb-0 lg:pb-8",
        className,
      )}
    >
      {children}
    </div>
  );
}

export function TerminusPuzzleTitle({
  children,
  className = "",
  ...props
}: PuzzleTitleProps) {
  return (
    <h1
      {...props}
      className={cn(
        "pt-2 text-center font-bold text-white transform-gpu drop-shadow-[0_2px_2px_rgba(0,0,0,0.75)]",
        className,
      )}
    >
      {children}
    </h1>
  );
}

export function TerminusPuzzleHeader({
  children,
  className = "",
  ...props
}: PuzzleHeaderProps) {
  return (
    <header
      {...props}
      className={cn(
        "relative p-2 sm:p-4 md:p-8 pt-24 sm:pt-24 md:pt-24",
        className,
      )}
    >
      <div id="puzzle-guess-section">{children}</div>
    </header>
  );
}

export function TerminusHintLink({
  slug,
  puzzleState,
}: {
  slug: string;
  puzzleState: TeamHuntState["puzzles"][string];
}) {
  return (
    <div className="absolute top-20 right-4 md:top-24 md:right-8 z-10 print:hidden">
      <HintLink slug={slug} puzzleState={puzzleState} />
    </div>
  );
}

export function TerminusMetaHintLink({
  slug,
  puzzleState,
}: {
  slug: string;
  puzzleState: TeamHuntState["puzzles"][string];
}) {
  return (
    <div className="fixed top-20 right-4 md:top-24 md:right-8 z-20 print:hidden">
      <HintLink slug={slug} puzzleState={puzzleState} />
    </div>
  );
}
