import { dontLeakThis } from "@hunt/anti-leak";
import React from "react";
import { useTeamState } from "../TeamStateProvider";
import twenty_years_into_the_future from "./assets/20_years_into_the_future.svg";
import acquisitions from "./assets/acquisitions.svg";
import back_and_forth from "./assets/back_and_forth.svg";
import bigbrain from "./assets/bigbrain.svg";
import combative_felines from "./assets/combative_felines.svg";
import devilish_devilries from "./assets/devilish_devilries.svg";
import endangered_species from "./assets/endangered_species.svg";
import functions from "./assets/functions.svg";
import genealogy from "./assets/genealogy.svg";
import greener_grass from "./assets/greener_grass.svg";
import had from "./assets/had.svg";
import in_the_air from "./assets/in_the_air.svg";
import invented_here from "./assets/invented_here.svg";
import invitation from "./assets/invitation.svg";
import make_your_own_boat from "./assets/make_your_own_boat.svg";
import multidimensional_crossword from "./assets/multidimensional_crossword.svg";
import normal_jigsaw from "./assets/normal_jigsaw.svg";
import not_tricked from "./assets/not_tricked.svg";
import pandemic from "./assets/pandemic.svg";
import partners_in_crime from "./assets/partners_in_crime.svg";
import ripped_paper from "./assets/ripped_paper.png";
import setting_boundaries from "./assets/setting_boundaries.svg";
import short_stories from "./assets/short_stories.svg";
import stray_child from "./assets/stray_child.svg";
import trivial_pursuit from "./assets/trivial_pursuit.svg";

// Make sure these are only ever rendered on the server side.
const HYPERBOLIC_SPACE_SVGS: Record<string, string> = dontLeakThis({
  acquisitions,
  combative_felines,
  devilish_devilries,
  functions,
  had,
  in_the_air,
  invented_here,
  invitation,
  make_your_own_boat,
  multidimensional_crossword,
  normal_jigsaw,
  "20_years_into_the_future": twenty_years_into_the_future,
  back_and_forth,
  bigbrain,
  endangered_species,
  genealogy,
  greener_grass,
  not_tricked,
  partners_in_crime,
  setting_boundaries,
  short_stories,
  stray_child,
  trivial_pursuit,
  pandemic,
});

export function HyperbolicSpacePostSolveSection({ slug }: { slug: string }) {
  const { puzzles } = useTeamState();
  // if not H-Space puzzle, return nothing
  if (!(slug in HYPERBOLIC_SPACE_SVGS)) {
    return <></>;
  }
  // if not solved, return nothing
  if (!puzzles[slug]?.answer) {
    return <></>;
  }

  const asset = HYPERBOLIC_SPACE_SVGS[slug];

  return (
    <div className="flex justify-center flex-col items-center">
      <span className="text-base italic text-white">
        You&apos;ve solved the puzzle, but you find this...
      </span>
      <div className="relative w-72 h-72">
        <img
          src={ripped_paper}
          alt="A ripped paper"
          className="w-72 h-72 absolute top-0 left-0 z-0 pointer-events-none"
        />
        <a href={asset} target="_blank" rel="noopener noreferrer">
          <img
            src={asset}
            alt="A heptagonal diagram"
            className="w-48 h-48 absolute top-1/2 left-1/2 z-10"
            style={{ transform: "translate(-50%, -50%)" }} // ← center it!
          />
        </a>
      </div>
    </div>
  );
}
